import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { CONFIG } from '../../config';

/* =====================================================================
   HÌNH HỌC NGƯỜI ĐI BỘ — một hình gộp cho mọi kiểu người (spec G5, G8): thân, đầu, tóc, hai tay (bắp tay áo cộc + cẳng tay),
   hai chân (đùi + ống quần + giày), nón lá, ba lô. Theo personGeo của bản dựng thử, bớt cạnh để ≤ CONFIG.people.maxVerts đỉnh.
   Mét, tỉ lệ 1: cao ≈ 1,65 m (≈ 1,79 m tính chóp nón), mặt hướng +X, rộng theo Z, chân chạm y = 0. Có index, không uv.
   Thuộc tính đỉnh (shader ở material.ts đọc):
   - aPart: 0 thân/đầu/tóc, 1 chân trái (−Z, vì mặt hướng +X), 2 chân phải (+Z), 3 tay trái, 4 tay phải, 5 nón lá, 6 ba lô (5, 6 bật theo cờ instance)
   - aSeg: 0 đoạn trên, 1 đoạn dưới khớp (quay thêm quanh aPivot2); aPivot: cao độ hông / vai; aPivot2: cao độ gối / khuỷu
   - aMask: 0 màu cố định aFix, 1 áo (instanceColor), 2 quần (aPants); aFix: màu cố định tuyến tính (da, tóc, giày, nón, ba lô)
   ===================================================================== */
export const PP_HIP = 0.86, PP_KNEE = 0.46, PP_SHOULDER = 1.37, PP_ELBOW = 1.1;   // m — cao độ khớp ở tỉ lệ 1
export enum PpPart { Body = 0, LegL = 1, LegR = 2, ArmL = 3, ArmR = 4, Hat = 5, Pack = 6 }
export enum PpMask { Fixed = 0, Shirt = 1, Pants = 2 }

const C = CONFIG.people.palette;
const cap = (r: number, l: number) => new THREE.CapsuleGeometry(r, l, 2, 6);   // tay chân: 6 cạnh, nắp 2 đoạn

/* Gắn thuộc tính khớp và màu cho một bộ phận; bỏ uv để mọi phần gộp được */
function ppTag(g: THREE.BufferGeometry, part: PpPart, pivot: number, fix: number, mask: PpMask, seg = 0, pivot2 = 0): THREE.BufferGeometry {
  if (g.getAttribute('uv')) g.deleteAttribute('uv'); g.clearGroups();
  const n = g.getAttribute('position').count, col = new THREE.Color(fix), F = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { F[i * 3] = col.r; F[i * 3 + 1] = col.g; F[i * 3 + 2] = col.b; }
  const fill = (v: number) => new THREE.BufferAttribute(new Float32Array(n).fill(v), 1);
  g.setAttribute('aPart', fill(part)); g.setAttribute('aSeg', fill(seg)); g.setAttribute('aPivot', fill(pivot)); g.setAttribute('aPivot2', fill(pivot2));
  g.setAttribute('aMask', fill(mask)); g.setAttribute('aFix', new THREE.BufferAttribute(F, 3));
  return g;
}

/* Dựng mới mỗi lần gọi (không cache): bên gọi giữ một bản dùng chung cho mọi hệ người nếu muốn */
export function ppBuildGeometry(): THREE.BufferGeometry {
  const parts = [
    ppTag(cap(0.15, 0.3).scale(0.78, 1, 1.18).translate(0, 1.12, 0), PpPart.Body, 0, C.skin, PpMask.Shirt),                     // thân (áo)
    ppTag(new THREE.SphereGeometry(0.115, 8, 6).translate(0, 1.54, 0), PpPart.Body, 0, C.skin, PpMask.Fixed),                    // đầu
    ppTag(new THREE.SphereGeometry(0.123, 8, 4, 0, Math.PI * 2, 0, 1.75).translate(-0.018, 1.553, 0), PpPart.Body, 0, C.hair, PpMask.Fixed),   // tóc (chỏm cầu, lệch ra sau)
    ppTag(new THREE.ConeGeometry(0.31, 0.17, 10).translate(0, 1.7, 0), PpPart.Hat, 0, C.hat, PpMask.Fixed),                      // nón lá
    ppTag(new THREE.BoxGeometry(0.13, 0.32, 0.25).translate(-0.18, 1.17, 0), PpPart.Pack, 0, C.pack, PpMask.Fixed)               // ba lô sau lưng (−X)
  ];
  for (const [side, leg, arm] of [[-1, PpPart.LegL, PpPart.ArmL], [1, PpPart.LegR, PpPart.ArmR]] as [number, PpPart, PpPart][]) {
    parts.push(ppTag(cap(0.072, 0.28).translate(0, 0.66, side * 0.085), leg, PP_HIP, C.skin, PpMask.Pants));                                    // đùi
    parts.push(ppTag(cap(0.058, 0.3).translate(0, 0.25, side * 0.085), leg, PP_HIP, C.skin, PpMask.Pants, 1, PP_KNEE));                          // ống chân
    parts.push(ppTag(new THREE.BoxGeometry(0.23, 0.07, 0.095).translate(0.045, 0.035, side * 0.085), leg, PP_HIP, C.shoe, PpMask.Fixed, 1, PP_KNEE));   // giày, mũi về +X
    parts.push(ppTag(cap(0.05, 0.18).translate(0, 1.235, side * 0.225), arm, PP_SHOULDER, C.skin, PpMask.Shirt));                                // bắp tay (áo cộc tay)
    parts.push(ppTag(cap(0.042, 0.2).translate(0, 0.96, side * 0.225), arm, PP_SHOULDER, C.skin, PpMask.Fixed, 1, PP_ELBOW));                    // cẳng tay
  }
  const g = mergeGeometries(parts);
  parts.forEach((p) => p.dispose());
  return g;
}
import { CONFIG } from '../../config';

/* =====================================================================
   DÁNG ĐI / DÁNG CHẠY NGƯỜI ĐI BỘ — bản CPU của shader trong material.ts (spec §5, G6, G7).
   Shader mới là chỗ chạy thật; file này giữ cùng công thức để unit test kiểm (tests/people-unit/gait.test.ts)
   và để code dựng tính nhịp bước (aVar.w) cho từng người. Đổi công thức ở đây thì sửa cả PP_GLSL_ANGLES trong material.ts.
   Góc dương = đưa về phía trước (người hướng +X, quay quanh trục Z). φ là pha chu kỳ hai bước:
   chân trái φ, chân phải φ + π, tay ngược pha chân cùng bên. Trộn đi ↔ chạy theo biên độ: run = smoothstep(0,42; 0,6; A).
   ===================================================================== */
export type PersonKind = 'walk' | 'run' | 'stand';
export type PersonPart = 'legL' | 'legR' | 'armL' | 'armR';
const P = CONFIG.people;

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const smoothstep = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
/* Mức chạy 0..1 theo biên độ hông (đi 0,34 → 0, chạy 0,6 → 1) */
export const ppRunMix = (amp: number) => smoothstep(0.42, 0.6, amp);
/* Biên độ hông theo kiểu người */
export const ppAmp = (kind: PersonKind) => (kind === 'walk' ? P.walk.amp : kind === 'run' ? P.run.amp : 0);

/* Nhịp (rad/s của φ). Đi: chân trụ không trượt ⇔ ω · bước / 2π = v. Chạy: nhịp cố định, người nhỏ bước nhanh hơn. Đứng: 0 */
export function ppCadence(kind: PersonKind, speed: number, scale: number): number {
  if (kind === 'walk') return (2 * Math.PI * speed) / (4 * P.legLength * scale * Math.sin(P.walk.amp));
  if (kind === 'run') return P.run.cadence / Math.sqrt(scale);
  return 0;
}

/* Quãng đường một chu kỳ hai bước (m): mỗi bước chân trụ quét dây cung 2·L·sin A. Chạy ở tỉ lệ 1 ≈ 1,94 m, khớp 2,6–3,0 m/s ở 1,4 chu kỳ/giây */
export function ppStride(kind: PersonKind, scale: number): number {
  return kind === 'stand' ? 0 : 4 * P.legLength * scale * Math.sin(ppAmp(kind));
}

/* Góc khớp: root = hông / vai, joint = gối (≤ 0, gập về sau) / khuỷu (≥ 0, gập về trước). Không tính tư thế chụp ảnh (cờ 4, chỉ có trong shader).
   jump = true (cờ 8, nhân vật đi dạo đang nhảy): tư thế cố định CONFIG.people.jump, không theo pha, hai bên như nhau; trong shader xét trước cờ chụp ảnh */
export function ppAngles(part: PersonPart, amp: number, phase: number, jump = false): { root: number; joint: number } {
  if (jump) { const J = P.jump; return part === 'legL' || part === 'legR' ? { root: J.hip, joint: J.knee } : { root: J.shoulder, joint: J.elbow }; }
  const A = amp, run = ppRunMix(A);
  if (part === 'legL' || part === 'legR') {
    const f = part === 'legL' ? phase : phase + Math.PI;
    const sw = Math.max(0, Math.cos(f - 0.35)), sr = Math.max(0, Math.cos(f + 0.45));   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
    const knee = A * 2 * sw * sw + (A >= 0.01 ? 0.06 : 0);
    return { root: A * Math.sin(f) + lerp(0.12 * A, 0.22, run), joint: -lerp(knee, 0.38 + 1.5 * sr * sr, run) };
  }
  const f = part === 'armL' ? phase + Math.PI : phase;
  return { root: A * (0.65 + run * 0.5) * Math.sin(f) - 0.05, joint: 0.16 + run * 1.25 + A * 0.35 * Math.max(0, Math.sin(f)) };
}
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { shared } from '../../core/shared';

/* =====================================================================
   VẬT LIỆU NGƯỜI ĐI BỘ — một vật liệu dùng chung cho mọi hệ người (spec G5–G8, §5), theo patchPerson của bản dựng thử.
   Tay chân vung trong vertex shader theo shared.uTime, không cập nhật đỉnh trên CPU. Công thức góc khớp giống hệt gait.ts (ppAngles).
   Thuộc tính instance (bên dựng gắn vào hình học của từng InstancedMesh):
   - aVar (vec4): x pha φ0 (rad), y biên độ hông A (0 đứng, walk.amp, run.amp), z cờ (1 nón lá, 2 ba lô, 4 chụp ảnh, 8 nhảy — chỉ nhân vật đi dạo bật, người đi bộ cũ không bao giờ có), w nhịp (rad/s, ppCadence)
   - aPants (vec3): màu quần tuyến tính; màu áo qua instanceColor (setColorAt — bắt buộc gọi để có USE_INSTANCING_COLOR)
   Người không đổ bóng, không vào phản chiếu (spec §6) nên không có vật liệu bóng riêng. Không emissive, không texture.
   Không thêm vào tập bóc mặt cắt hầm (cutaway.ts): người không đứng trong vùng bóc, vật liệu người cũ cũng không có trong tập đó.
   ===================================================================== */
const P = CONFIG.people;
const f = (x: number) => x.toFixed(4);   // số → hằng GLSL

/* pAngles: x góc khớp gốc (hông / vai), y góc khớp giữa (gối / khuỷu); dương = đưa về phía trước. Bản CPU: gait.ts ppAngles */
const VS_HEAD = /* glsl */`
attribute float aPart;
attribute float aSeg;
attribute float aPivot;
attribute float aPivot2;
attribute float aMask;
attribute vec3 aFix;
attribute vec4 aVar;
attribute vec3 aPants;
uniform float uTime;
float pFlag( float b ) { return mod( floor( aVar.z / b ), 2.0 ); }
float pRunMix() { return smoothstep( 0.42, 0.6, aVar.y ); }
float pPhase() { return uTime * aVar.w + aVar.x; }
vec2 pAngles() {
  float A = aVar.y, ph = pPhase(), run = pRunMix();
  if ( aPart > 0.5 && aPart < 2.5 ) {
    if ( pFlag( 8.0 ) > 0.5 ) return vec2( ${f(P.jump.hip)}, ${f(P.jump.knee)} );   // nhảy (chỉ nhân vật đi dạo): co gối
    float fl = aPart < 1.5 ? ph : ph + 3.14159265;
    float sw = max( 0.0, cos( fl - 0.35 ) ), sr = max( 0.0, cos( fl + 0.45 ) );   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
    return vec2( A * sin( fl ) + mix( 0.12 * A, 0.22, run ), -mix( A * 2.0 * sw * sw + 0.06 * step( 0.01, A ), 0.38 + 1.5 * sr * sr, run ) );
  }
  if ( aPart > 2.5 && aPart < 4.5 ) {
    float fa = aPart < 3.5 ? ph + 3.14159265 : ph;
    if ( pFlag( 8.0 ) > 0.5 ) return vec2( ${f(P.jump.shoulder)}, ${f(P.jump.elbow)} );   // nhảy: hai vai đưa lên
    if ( aPart > 3.5 && pFlag( 4.0 ) > 0.5 ) return vec2( ${f(P.photo.shoulder)}, ${f(P.photo.elbow)} );   // giơ tay phải chụp ảnh
    return vec2( A * ( 0.65 + run * 0.5 ) * sin( fa ) - 0.05, 0.16 + run * 1.25 + A * 0.35 * max( 0.0, sin( fa ) ) );
  }
  return vec2( 0.0 );
}
vec2 pRot( vec2 p, float a ) { float c = cos( a ), s = sin( a ); return vec2( p.x * c - p.y * s, p.x * s + p.y * c ); }
`;
// pháp tuyến quay cùng khớp (beginnormal_vertex chạy trước begin_vertex nên ppA dùng lại được)
const VS_NORMAL = /* glsl */`#include <beginnormal_vertex>
vec2 ppA = pAngles();
float ppLean = ( aPart < 0.5 || aPart > 2.5 ) ? -${f(P.run.lean)} * pRunMix() : 0.0;
objectNormal.xy = pRot( objectNormal.xy, ppA.x + ( aSeg > 0.5 ? ppA.y : 0.0 ) + ppLean );`;
const VS_POS = /* glsl */`#include <begin_vertex>
if ( aSeg > 0.5 ) transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot2 ), ppA.y ) + vec2( 0.0, aPivot2 );
transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot ), ppA.x ) + vec2( 0.0, aPivot );
transformed.xy = pRot( transformed.xy - vec2( 0.0, ${f(P.legLength)} ), ppLean ) + vec2( 0.0, ${f(P.legLength)} );   // chạy: thân, đầu, tay đổ về trước quanh hông
if ( aPart > 4.5 && aPart < 5.5 && pFlag( 1.0 ) < 0.5 ) transformed = vec3( 0.0 );   // không đội nón: thu về gốc (tam giác suy biến)
if ( aPart > 5.5 && pFlag( 2.0 ) < 0.5 ) transformed = vec3( 0.0 );                  // không đeo ba lô
float ppPh = pPhase(), ppMove = step( 0.01, aVar.y );
transformed.y += mix( ${f(P.bob.walk)} * cos( 2.0 * ppPh ) - ${f(P.bob.walk)}, ${f(P.bob.run)} * ( 0.5 - 0.5 * cos( 2.0 * ppPh ) ), pRunMix() ) * ppMove;   // đi: thấp nhất khi hai chân dang rộng; chạy: bật lên giữa hai bước
transformed.z += ${f(P.sway)} * sin( ppPh ) * ppMove * smoothstep( 0.3, 1.6, transformed.y );   // lắc vai nhẹ sang hai bên`;
const VS_COLOR = /* glsl */`#include <color_vertex>
#ifdef USE_INSTANCING_COLOR
vColor.rgb = aMask < 0.5 ? aFix : ( aMask < 1.5 ? instanceColor.rgb : aPants );   // cố định / áo / quần
#endif`;

let mat: THREE.MeshStandardMaterial | null = null;
/* Một vật liệu cho mọi hệ người (tạo lần đầu gọi) */
export function ppMaterial(): THREE.MeshStandardMaterial {
  if (mat) return mat;
  const m = new THREE.MeshStandardMaterial({ roughness: P.roughness });
  m.name = 'peopleWalk';
  m.onBeforeCompile = (s) => {
    s.uniforms.uTime = shared.uTime;
    s.vertexShader = VS_HEAD + s.vertexShader.replace('#include <beginnormal_vertex>', VS_NORMAL).replace('#include <begin_vertex>', VS_POS).replace('#include <color_vertex>', VS_COLOR);
    m.userData.vs = s.vertexShader;
  };
  m.customProgramCacheKey = () => 'peopleWalk';
  return (mat = m);
}
import { CONFIG } from '../../config';
import { rng } from '../math';
import type { PersonKind } from './gait';

/* =====================================================================
   CHIA KIỂU NGƯỜI (spec G8, §7) — chọn theo chỉ số trên danh sách người đang có, tổng số không đổi.
   Dùng rng(seed) riêng (không gọi rand(), không đụng rnd của cầu). Số người mỗi kiểu = làm tròn n × CONFIG.people.mix.
   - Người đi cùng (đi đôi hoặc trẻ em) i luôn theo người i − 1; người i − 1 đi bộ một mình (không chạy, không đứng, không đi cùng ai).
   - Trẻ em: tỉ lệ childScale, luôn là người đi cùng. Người chụp ảnh: chỉ trong số người đứng.
   - flags = tổng cờ PP_FLAG (khớp aVar.z trong material.ts).
   ===================================================================== */
export const PP_FLAG = { hat: 1, pack: 2, photo: 4, jump: 8 } as const;   // jump: chỉ nhân vật đi dạo bật (explore/stroll/avatars.ts), ppAssignKinds không bao giờ gán
export interface PersonInfo { kind: PersonKind; scale: number; flags: number; phase: number; follow: number /* chỉ số người mình đi cùng, −1 nếu không */ }

/* Xáo trộn Fisher–Yates bằng bộ sinh r */
function ppShuffle<T>(a: T[], r: () => number): T[] {
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

export function ppAssignKinds(n: number, seed: number, opts?: { run?: boolean }): PersonInfo[] {
  const P = CONFIG.people, M = P.mix, r = rng(seed), [s0, s1] = P.adultScale;
  const out: PersonInfo[] = Array.from({ length: n }, () => ({ kind: 'walk' as PersonKind, scale: s0 + r() * (s1 - s0), flags: 0, phase: r() * Math.PI * 2, follow: -1 }));
  // người đi cùng: chọn chỉ số i ≥ 1 sao cho i − 1 và i + 1 không cũng là người đi cùng (người dẫn không đi cùng ai)
  const comp = new Set<number>(), nComp = Math.round(n * M.companion);
  for (const i of ppShuffle(Array.from({ length: Math.max(0, n - 1) }, (_, k) => k + 1), r)) {
    if (comp.size >= nComp) break;
    if (!comp.has(i - 1) && !comp.has(i + 1)) comp.add(i);
  }
  const compList = [...comp].sort((a, b) => a - b);
  for (const i of compList) out[i].follow = i - 1;
  for (const i of ppShuffle(compList.slice(), r).slice(0, Math.round(compList.length * M.child))) out[i].scale = P.childScale;
  // người đứng và người chạy: lấy từ những người không đi cùng và không dẫn ai
  const free = ppShuffle(out.map((_, i) => i).filter((i) => !comp.has(i) && !comp.has(i + 1)), r);
  const nStand = Math.min(free.length, Math.round(n * M.stand)), nRun = opts?.run === false ? 0 : Math.min(free.length - nStand, Math.round(n * M.run));
  const stand = free.slice(0, nStand);
  for (const i of stand) out[i].kind = 'stand';
  for (const i of free.slice(nStand, nStand + nRun)) out[i].kind = 'run';
  // cờ: nón lá, ba lô trên mọi người; chụp ảnh trong số người đứng
  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.hat))) out[i].flags |= PP_FLAG.hat;
  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.pack))) out[i].flags |= PP_FLAG.pack;
  for (const i of ppShuffle(stand.slice(), r).slice(0, Math.round(stand.length * M.photo))) out[i].flags |= PP_FLAG.photo;
  return out;
}
/* ===== Đi dạo: nhân vật hiển thị (mình + tối đa 4 người khác) =====
   Một InstancedMesh 5 instance (chỉ số = slot đi dạo; đi một mình dùng 0), hình người đi bộ có sẵn (ppBuildGeometry) và vật liệu dùng chung (ppMaterial):
   tay chân vung trong shader theo aVar, nên đổi dáng chỉ là ghi 4 số của instance. Lớp 1 (không vào phản chiếu nước), không đổ bóng: thêm đúng 1 lệnh vẽ.
   Áo màu multiParams.colors[slot] (như cánh dù), quần một màu tối CONFIG.stroll.pants. Instance trống thu về scale 0; không ai hiện thì mesh.visible = false.
   Người khác nội suy bằng ExTrack như remote.ts (trường thứ 6 chở pose, lấy mẫu bậc thang step = true); slot đổi chủ thì xóa mẫu và ẩn tới mẫu đầu.
   build() chỉ dựng (lần đầu gọi, không lúc dựng cảnh), bên gọi tự thêm vào scene. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { shared } from '../../core/shared';
import { ppBuildGeometry } from '../../common/people/shapes';
import { ppMaterial } from '../../common/people/material';
import { ppAmp, ppCadence, ppStride } from '../../common/people/gait';
import { PP_FLAG } from '../../common/people/kinds';
import { ExTrack, type ExPose } from '../multi/interp';
import type { Flyer } from '../multi/protocol';
import { ST_POSE_WALK, ST_POSE_RUN, ST_POSE_JUMP, ST_POSE_PHOTO, type StState } from './motion';

const M = CONFIG.explore.multi, C = CONFIG.stroll, N = M.stroll.slots, TAU = Math.PI * 2;

/* Thuần: dáng (pose) + tốc độ (m/s) → biên độ hông, nhịp (rad/s của φ), cờ instance (khớp aVar của material.ts).
   Nhịp theo tốc độ cho chân trụ không trượt (đi: bước đi; chạy: bước chạy, không chậm hơn nhịp chạy bộ), kẹp ≤ cadenceMax × run.cadence vì 3,5 / 10 m/s nhanh hơn người thật */
export function stAvatarVar(pose: number, speed: number, out: { amp: number; cadence: number; flags: number }): void {
  const cap = C.cadenceMax * CONFIG.people.run.cadence, v = Math.max(0, speed);
  out.amp = 0; out.cadence = 0; out.flags = 0;
  if (pose === ST_POSE_WALK) { out.amp = ppAmp('walk'); out.cadence = Math.min(cap, ppCadence('walk', v, 1)); }
  else if (pose === ST_POSE_RUN) { out.amp = ppAmp('run'); out.cadence = Math.min(cap, Math.max(ppCadence('run', v, 1), (TAU * v) / ppStride('run', 1))); }
  else if (pose === ST_POSE_JUMP) out.flags = PP_FLAG.jump;   // biên độ 0: không nhún, không lắc, không đổ người; tay chân theo tư thế nhảy cố định
  else if (pose === ST_POSE_PHOTO) out.flags = PP_FLAG.photo;
}

interface StSlot {
  who: 0 | 1 | 2;             // 0 trống, 1 mình, 2 người khác
  name: string | null;        // tên người khác (từ sync); null = không có
  track: ExTrack;
  pose: ExPose;               // đệm lấy mẫu (bank chở pose)
  st: { x: number; y: number; z: number; yaw: number; pose: number };   // trạng thái trả cho slotState
  live: boolean;              // đang hiện
  amp: number; cadence: number; flags: number;   // aVar đang ghi (để biết khi nào phải ghi lại)
}

const slots: StSlot[] = Array.from({ length: N }, () => ({
  who: 0 as const, name: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
  st: { x: 0, y: 0, z: 0, yaw: 0, pose: 0 }, live: false, amp: -1, cadence: -1, flags: -1
}));
let mesh: THREE.InstancedMesh | null = null, aVar: THREE.InstancedBufferAttribute | null = null, me = -1;
const _m = new THREE.Matrix4(), _q = new THREE.Quaternion(), _p = new THREE.Vector3(), _one = new THREE.Vector3(1, 1, 1), _zero = new THREE.Matrix4().makeScale(0, 0, 0), _up = new THREE.Vector3(0, 1, 0);
const _var = { amp: 0, cadence: 0, flags: 0 };

/* Ghi ma trận và aVar của slot i theo s.st (hoặc thu về scale 0 nếu không hiện); speed cho nhịp bước */
function stPlace(i: number, speed: number): void {
  const s = slots[i];
  if (!mesh || !aVar) return;
  if (!s.live) { mesh.setMatrixAt(i, _zero); mesh.instanceMatrix.needsUpdate = true; return; }
  const t = s.st;
  mesh.setMatrixAt(i, _m.compose(_p.set(t.x, t.y, t.z), _q.setFromAxisAngle(_up, t.yaw), _one));   // hình hướng +X: quay yaw quanh Y ra (cos yaw, 0, −sin yaw)
  mesh.instanceMatrix.needsUpdate = true;
  stAvatarVar(t.pose, speed, _var);
  if (_var.amp === s.amp && _var.cadence === s.cadence && _var.flags === s.flags) return;
  const a = aVar.array as Float32Array, o = i * 4, now = shared.uTime.value;
  const ph = now * a[o + 3] + a[o];   // giữ pha liền khi đổi nhịp: φ(now) không nhảy
  a[o] = (((ph - now * _var.cadence) % TAU) + TAU) % TAU; a[o + 1] = _var.amp; a[o + 2] = _var.flags; a[o + 3] = _var.cadence;
  s.amp = _var.amp; s.cadence = _var.cadence; s.flags = _var.flags;
  aVar.needsUpdate = true;
}

function stHide(i: number): void {
  const s = slots[i];
  s.track.reset(); s.live = false;
  stPlace(i, 0);
}

function stRefreshVisible(): void {
  if (!mesh) return;
  let any = false;
  for (const s of slots) if (s.live) { any = true; break; }
  mesh.visible = any;
}

/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);

export const stAvatars = {
  get mesh(): THREE.InstancedMesh | null { return mesh; },
  get self(): number { return me; },   // slot nhân vật của mình, -1 nếu không có (nhãn tên bỏ qua slot này)

  /* Dựng lần đầu gọi (lười, ngoài thứ tự dựng cảnh), các lần sau trả lại mesh cũ. Bên gọi thêm vào scene */
  build(): THREE.InstancedMesh {
    if (mesh) return mesh;
    const geo = ppBuildGeometry(), col = new THREE.Color();
    aVar = new THREE.InstancedBufferAttribute(new Float32Array(N * 4), 4); aVar.setUsage(THREE.DynamicDrawUsage);
    const pants = new Float32Array(N * 3);
    col.setHex(C.pants);
    for (let i = 0; i < N; i++) pants.set([col.r, col.g, col.b], i * 3);   // Color chuyển hex sRGB → tuyến tính
    geo.setAttribute('aVar', aVar);
    geo.setAttribute('aPants', new THREE.InstancedBufferAttribute(pants, 3));
    mesh = new THREE.InstancedMesh(geo, ppMaterial(), N);
    mesh.name = 'stroll-people';
    for (let i = 0; i < N; i++) { mesh.setColorAt(i, col.set(M.colors[i % M.colors.length])); mesh.setMatrixAt(i, _zero); }   // setColorAt bắt buộc (USE_INSTANCING_COLOR)
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.layers.set(1); mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
    for (const s of slots) s.amp = s.cadence = s.flags = -1;
    for (let i = 0; i < N; i++) stPlace(i, 0);
    stRefreshVisible();
    return mesh;
  },

  /* Nhân vật của mình ở slot (đi một mình: 0); s = null thì bỏ hiện slot đó */
  setSelf(slot: number, s: StState | null): void {
    if (s === null) {
      if (me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
      me = -1; stRefreshVisible(); return;
    }
    const x = slots[slot];
    if (!x) return;
    if (me !== slot && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
    me = slot; x.who = 1; x.track.reset();
    const t = x.st;
    t.x = s.x; t.y = s.y; t.z = s.z; t.yaw = s.yaw; t.pose = s.pose;
    x.live = true;
    stPlace(slot, s.speed);
    stRefreshVisible();
  },

  /* Danh sách người đi dạo đổi (sảnh, vào, ra): slot đổi chủ thì xóa mẫu, ẩn tới mẫu đầu; slot trống thì ẩn. Slot của mình do setSelf lo */
  sync(walkers: Flyer[], mySlot: number): void {
    if (mySlot !== me && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); me = -1; }   // đổi slot của mình: setSelf sẽ đặt lại
    for (let i = 0; i < N; i++) {
      const s = slots[i];
      let name: string | null = null;
      for (const w of walkers) if (w.slot === i) { name = w.name; break; }
      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
      if (name !== s.name || s.who !== 2) { s.name = name; s.who = 2; stHide(i); }
    }
    stRefreshVisible();
  },

  /* Gói vị trí gộp: w = [slot, x, y, z, yaw, pose, giờ gửi?]; chỉ nhận slot người khác đã biết chủ */
  onPos(w: number[][], nowMs: number): void {
    for (const e of w) {
      const i = e[0], s = slots[i];
      if (!s || i === me || s.who !== 2) continue;
      s.track.feed(e, nowMs, M);
    }
  },

  /* Mỗi khung: đặt người khác theo mẫu nội suy (pose bậc thang) */
  update(nowMs: number): void {
    const t = nowMs - M.interpSends * 1000 / M.sendHz;
    for (let i = 0; i < N; i++) {
      const s = slots[i];
      if (s.who !== 2) continue;
      if (!s.track.sample(t, s.pose, true)) { if (s.live) { s.live = false; stPlace(i, 0); } continue; }
      const p = s.pose, st = s.st;
      st.x = p.x; st.y = p.y; st.z = p.z; st.yaw = p.yaw; st.pose = Math.round(p.bank);
      s.live = true;
      stPlace(i, stPoseSpeed(st.pose));
    }
    stRefreshVisible();
  },

  /* Trạng thái đang hiện của slot (cho nhãn tên, camera dù lượn); null nếu trống hoặc chưa có mẫu */
  slotState(slot: number): { x: number; y: number; z: number; yaw: number; pose: number } | null {
    const s = slots[slot];
    return s && s.live ? s.st : null;
  },

  /* Tên người ở slot (theo sync, cả slot của mình); null nếu trống hoặc đi một mình */
  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },

  /* Rời chế độ / rời phòng: ẩn hết, quên tên (mesh giữ lại để tái dùng) */
  clear(): void {
    me = -1;
    for (let i = 0; i < N; i++) { const s = slots[i]; s.who = 0; s.name = null; stHide(i); }
    stRefreshVisible();
  }
};
/* ============================ Đi dạo: chuyển động nhân vật (thuần) ============================
   Mỗi khung: đọc đầu vào, đổi tốc độ / hướng mặt, nhảy, đi qua stMove (va chạm), bám cao độ đứng, chọn dáng (pose).
   Thuần: không import three, không đụng DOM. stStep chạy mỗi khung nên không cấp phát (D-018): dùng đối tượng tạm cấp module.
   - dt kẹp về dtMax: khung rất dài (tab ẩn rồi quay lại) không làm nhân vật vọt qua tường, chỉ chậm đi một khung.
   - Hướng: tới = (cos yaw, 0, −sin yaw), yaw tăng là quay trái (như flight.ts).
   - Cổng nhịp quay đóng dưới chân (vị trí không còn hợp lệ): stMove đóng băng khi điểm xuất phát không hợp lệ, nên sơ tán KHÔNG dùng stMove:
     tính một lần điểm hợp lệ gần nhất (stNearestValid, đắt), rồi đi thẳng tới đó với tốc độ chạy, bỏ qua đầu vào; tới nơi thì trả điều khiển. */
import { CONFIG } from '../../config';
import { stMove, stValid, stGroundY, stNearestValid, type StMap } from './map';
import { stSpawn } from './mapData';

export const ST_POSE_IDLE = 0, ST_POSE_WALK = 1, ST_POSE_RUN = 2, ST_POSE_JUMP = 3, ST_POSE_PHOTO = 4;

export interface StState {
  x: number; y: number; z: number;   // y: cao độ chân tuyệt đối, m
  yaw: number; speed: number;        // speed: tốc độ mặt bằng, m/s
  vy: number; air: boolean;          // vy: vận tốc đứng, m/s
  pose: number; evac: boolean;
  photo: number;                     // giây còn giơ tay chụp
  tx: number; tz: number;            // điểm sơ tán đã tính (chỉ có nghĩa khi evac)
}
export interface StInput { mx: number; mz: number; run: boolean; jump: boolean; camYaw: number }

const EPS_STEP = 1e-3;      // dung sai khi so bậc cao độ với stepMax (bậc Cầu Rồng lề ↔ bờ đo 0,3500083), m
const V_STOP = 0.1;         // m/s — dưới mức này coi là đứng yên
const _mv = { x: 0, z: 0 };      // kết quả stMov

