61	export type PersonKind = 'walk' | 'run' | 'stand';
62	export type PersonPart = 'legL' | 'legR' | 'armL' | 'armR';
63	const P = CONFIG.people;
64	
65	const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
66	const smoothstep = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
