68	export const ppRunMix = (amp: number) => smoothstep(0.42, 0.6, amp);
69	/* Biên độ hông theo kiểu người */
70	export const ppAmp = (kind: PersonKind) => (kind === 'walk' ? P.walk.amp : kind === 'run' ? P.run.amp : 0);
