84	/* Góc khớp: root = hông / vai, joint = gối (≤ 0, gập về sau) / khuỷu (≥ 0, gập về trước). Không tính tư thế chụp ảnh (cờ 4, chỉ có trong shader).
85	   jump = true (cờ 8, nhân vật đi dạo đang nhảy): tư thế cố định CONFIG.people.jump, không theo pha, hai bên như nhau; trong shader xét trước cờ chụp ảnh */
86	export function ppAngles(part: PersonPart, amp: number, phase: number, jump = false): { root: number; joint: number } {
87	  if (jump) { const J = P.jump; return part === 'legL' || part === 'legR' ? { root: J.hip, joint: J.knee } : { root: J.shoulder, joint: J.elbow }; }
88	  const A = amp, run = ppRunMix(A);
89	  if (part === 'legL' || part === 'legR') {
90	    const f = part === 'legL' ? phase : phase + Math.PI;
91	    const sw = Math.max(0, Math.cos(f - 0.35)), sr = Math.max(0, Math.cos(f + 0.45));   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
