93	    return { root: A * Math.sin(f) + lerp(0.12 * A, 0.22, run), joint: -lerp(knee, 0.38 + 1.5 * sr * sr, run) };
94	  }
95	  const f = part === 'armL' ? phase + Math.PI : phase;
96	  return { root: A * (0.65 + run * 0.5) * Math.sin(f) - 0.05, joint: 0.16 + run * 1.25 + A * 0.35 * Math.max(0, Math.sin(f)) };
