116	attribute float aPart;
117	attribute float aSeg;
118	attribute float aPivot;
119	attribute float aPivot2;
120	attribute float aMask;
121	attribute vec3 aFix;
122	attribute vec4 aVar;
123	attribute vec3 aPants;
124	uniform float uTime;
