132	    float fl = aPart < 1.5 ? ph : ph + 3.14159265;
133	    float sw = max( 0.0, cos( fl - 0.35 ) ), sr = max( 0.0, cos( fl + 0.45 ) );   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
