135	  }
136	  if ( aPart > 2.5 && aPart < 4.5 ) {
137	    float fa = aPart < 3.5 ? ph + 3.14159265 : ph;
138	    if ( pFlag( 8.0 ) > 0.5 ) return vec2( ${f(P.jump.shoulder)}, ${f(P.jump.elbow)} );   // nhảy: hai vai đưa lên
