183	/* =====================================================================
184	   CHIA KIỂU NGƯỜI (spec G8, §7) — chọn theo chỉ số trên danh sách người đang có, tổng số không đổi.
185	   Dùng rng(seed) riêng (không gọi rand(), không đụng rnd của cầu). Số người mỗi kiểu = làm tròn n × CONFIG.people.mix.
186	   - Người đi cùng (đi đôi hoặc trẻ em) i luôn theo người i − 1; người i − 1 đi bộ một mình (không chạy, không đứng, không đi cùng ai).
187	   - Trẻ em: tỉ lệ childScale, luôn là người đi cùng. Người chụp ảnh: chỉ trong số người đứng.
188	   - flags = tổng cờ PP_FLAG (khớp aVar.z trong material.ts).
189	   ===================================================================== */
190	export const PP_FLAG = { hat: 1, pack: 2, photo: 4, jump: 8 } as const;   // jump: chỉ nhân vật đi dạo bật (explore/stroll/avatars.ts), ppAssignKinds không bao giờ gán
191	export interface PersonInfo { kind: PersonKind; scale: number; flags: number; phase: number; follow: number /* chỉ số người mình đi cùng, −1 nếu không */ }
192	
193	/* Xáo trộn Fisher–Yates bằng bộ sinh r */
194	function ppShuffle<T>(a: T[], r: () => number): T[] {
195	  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
196	  return a;
197	}
198	
199	export function ppAssignKinds(n: number, seed: number, opts?: { run?: boolean }): PersonInfo[] {
200	  const P = CONFIG.people, M = P.mix, r = rng(seed), [s0, s1] = P.adultScale;
201	  const out: PersonInfo[] = Array.from({ length: n }, () => ({ kind: 'walk' as PersonKind, scale: s0 + r() * (s1 - s0), flags: 0, phase: r() * Math.PI * 2, follow: -1 }));
202	  // người đi cùng: chọn chỉ số i ≥ 1 sao cho i − 1 và i + 1 không cũng là người đi cùng (người dẫn không đi cùng ai)
203	  const comp = new Set<number>(), nComp = Math.round(n * M.companion);
204	  for (const i of ppShuffle(Array.from({ length: Math.max(0, n - 1) }, (_, k) => k + 1), r)) {
205	    if (comp.size >= nComp) break;
206	    if (!comp.has(i - 1) && !comp.has(i + 1)) comp.add(i);
207	  }
208	  const compList = [...comp].sort((a, b) => a - b);
209	  for (const i of compList) out[i].follow = i - 1;
210	  for (const i of ppShuffle(compList.slice(), r).slice(0, Math.round(compList.length * M.child))) out[i].scale = P.childScale;
211	  // người đứng và người chạy: lấy từ những người không đi cùng và không dẫn ai
212	  const free = ppShuffle(out.map((_, i) => i).filter((i) => !comp.has(i) && !comp.has(i + 1)), r);
213	  const nStand = Math.min(free.length, Math.round(n * M.stand)), nRun = opts?.run === false ? 0 : Math.min(free.length - nStand, Math.round(n * M.run));
214	  const stand = free.slice(0, nStand);
215	  for (const i of stand) out[i].kind = 'stand';
216	  for (const i of free.slice(nStand, nStand + nRun)) out[i].kind = 'run';
217	  // cờ: nón lá, ba lô trên mọi người; chụp ảnh trong số người đứng
218	  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.hat))) out[i].flags |= PP_FLAG.hat;
219	  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.pack))) out[i].flags |= PP_FLAG.pack;
220	  for (const i of ppShuffle(stand.slice(), r).slice(0, Math.round(stand.length * M.photo))) out[i].flags |= PP_FLAG.photo;
221	  return out;
222	}
223	/* ===== Đi dạo: nhân vật hiển thị (mình + tối đa 4 người khác) =====
224	   Một InstancedMesh 5 instance (chỉ số = slot đi dạo; đi một mình dùng 0), hình người đi bộ có sẵn (ppBuildGeometry) và vật liệu dùng chung (ppMaterial):
225	   tay chân vung trong shader theo aVar, nên đổi dáng chỉ là ghi 4 số của instance. Lớp 1 (không vào phản chiếu nước), không đổ bóng: thêm đúng 1 lệnh vẽ.
